<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { systemApi, type Department } from '@/api/system'
const rows=ref<Department[]>([]),visible=ref(false),editingId=ref<number|null>(null),loading=ref(false)
const form=reactive({parentId:null as number|null,code:'',name:'',status:'ENABLED',version:0})
const tree=computed(()=>{const map=new Map<number,any>();rows.value.forEach(d=>map.set(d.id,{...d,children:[]}));const roots:any[]=[];map.forEach(d=>d.parentId&&map.has(d.parentId)?map.get(d.parentId).children.push(d):roots.push(d));return roots})
async function load(){loading.value=true;try{rows.value=await systemApi.departments()}finally{loading.value=false}}
function create(parentId:number|null=null){editingId.value=null;Object.assign(form,{parentId,code:'',name:'',status:'ENABLED',version:0});visible.value=true}
function edit(row:Department){editingId.value=row.id;Object.assign(form,row);visible.value=true}
async function save(){if(editingId.value)await systemApi.updateDepartment(editingId.value,form);else await systemApi.createDepartment(form);visible.value=false;ElMessage.success('部门已保存');await load()}
async function remove(row:Department){await ElMessageBox.confirm(`确定删除部门“${row.name}”吗？`,'删除确认',{type:'warning'});await systemApi.deleteDepartment(row.id);ElMessage.success('已删除');await load()}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p>ORGANIZATION</p><h1>部门管理</h1></div><el-button type="primary" @click="create()">新增部门</el-button></div><div class="content-card"><el-table v-loading="loading" :data="tree" row-key="id" default-expand-all><el-table-column prop="name" label="部门名称"/><el-table-column prop="code" label="编码"/><el-table-column prop="path" label="组织路径"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.status==='ENABLED'?'success':'info'">{{s.row.status==='ENABLED'?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="310"><template #default="s"><div class="system-action-group"><el-button class="system-action system-add-action" @click="create(s.row.id)">新增下级</el-button><el-button class="system-action system-edit-action" @click="edit(s.row)">编辑</el-button><el-button class="system-action system-delete-action" @click="remove(s.row)">删除</el-button></div></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editingId?'编辑部门':'新增部门'" width="500px"><el-form label-width="90px"><el-form-item label="上级部门"><el-select v-model="form.parentId" clearable style="width:100%"><el-option v-for="d in rows.filter(x=>x.id!==editingId)" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="部门编码"><el-input v-model="form.code"/></el-form-item><el-form-item label="部门名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="ENABLED">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
